local NS68_GUN_AT, NS68_MOVE_AT = 192, 372
local function card68_init(owner)
    EX.clear_records(owner)
    EX.pool_clear()
    owner.lwns_t = 0
    owner.lwns_gun = nil
    owner.lwns_r1, owner.lwns_r2 = 0.5, 0.25   -- 见 shot() 上面的 rank 注
