local TIMELINE_S1BACK = {
    {     0,  5,  -112,    240,   300, 0,  1 },
    {   100,  3,   112,    240,   400, 1,  1 },
    {   400,  3,  -112,    240,   300, 0,  1 },
    {   500,  5,   112,    240,   400, 1,  1 },
    {   800,  5,  -112,    240,   300, 0,  1 },
    {   800, 11,   112,    240,   400, 1,  1 },
