    {  1900,  0,   208,   160,    30, 1,   0 },
    {  1910,  0,   208,   160,    30, 1,   1 },
    {  1920,  0,   208,   160,    30, 1,   0 },
    {  1930,  0,   208,   160,    30, 1,   1 },
