    local head = #s + 1
    add(120, function(u)
        u.lf0 = u.ma + 1.57079637                 ---原作 FLOAT_SUB2 lf0 moveAngle π/2
        E.shoot(u, { op = 97, type = 1, color = 2, count1 = 1, count2 = 1,
                     speed1 = 1.6, speed2 = 0.8, angle = u.lf0, step = 0, flags = 0x203 })
    end)
    add(120, function(u, c) c.stall = u.li0 end)
    add(120, function() return { t = 120, pc = head } end)
    SUB24 = s
end

---Sub26（Sub25 的枪）：**t=120 起**每 li0 = 11 帧一轮、方向 = 本机移动方向 + π/2、
---速度 lf7 = 2.1 → 1.2、弹种 7 / 色 3、2 发一扇。
local SUB26
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(120, function(u)
        u.li0 = 11
        u.lf7 = 2.1
    end)
    local head = #s + 1
    add(120, function(u)
        u.lf0 = u.ma - 1.57079637                 ---原作 FLOAT_ADD2 lf0 moveAngle π/2
        E.shoot(u, { op = 97, type = 7, color = 3, count1 = 1, count2 = 2,
                     speed1 = u.lf7, speed2 = 1.2, angle = u.lf0, step = 0, flags = 0x200 })
    end)
    add(120, function(u, c) c.stall = u.li0 end)
    add(120, function() return { t = 120, pc = head } end)
    SUB26 = s
end

---Sub28（Sub27 的枪）：**t=120 起**每 li0 帧一发，方向 = 本机移动方向、
---速度 lf7 = 3 → 1.2、弹种 1 / 色 2、2 发一扇。
---★ li0 初值 23 **大于** 16 ⇒ 原作 `JMP_IF_INT_LE li0 16`（跳到 stall 那条、
---  绕过 DEC）在头几轮**不成立**，于是 `INT_DEC li0` 真的执行：间隔从 22 逐轮
---  递减到 16 后固定 16（原作 li0 = 23→22→…→16，到 16 后跳转成立、不再减）。
---  同一模板里的 Sub6/8/14/19/21/26 初值都 ≤ 16 ⇒ 那条 DEC 恒被跳过（死代码），
---  只有本子程序要吃它。
local SUB28
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(120, function(u)
        u.li0 = 23
        u.lf7 = 3
    end)
    local head = #s + 1
    add(120, function(u)
        u.lf0 = u.ma + PI                       ---原作 FLOAT_ADD2 lf0 moveAngle π（死代码）
        E.shoot(u, { op = 97, type = 1, color = 2, count1 = 1, count2 = 2,
                     speed1 = u.lf7, speed2 = 1.2, angle = u.ma, step = 0, flags = 0x202 })
    end)
    add(120, function(u, c)                     ---#5 JMP_IF_INT_LE li0 16 → stall（跳过 #6）
        if u.li0 > 16 then u.li0 = u.li0 - 1 end ---#6 INT_DEC li0
        c.stall = u.li0                          ---#7 SET_SECONDARY_TIME li0
    end)
    add(120, function() return { t = 120, pc = head } end)
    SUB28 = s
end

---Sub29/31（时间轴直接生成的小妖精，life 200）：t=20 挂枪，t=140 起转向 +π/4（我们口径）
---并以 0.0333 px/帧² 加速飞走，t=5140 退场。出生免伤 20（表里）。
local function make_sprinkler(gun)
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    ---原作的 `DISABLE_INTERACTION_FLAGS 2`（清 COLLISION）在移植版恒成立（一律 NONTJT）。
    add(20, function(u) E.child(u, gun) end)
    add(140, function(u)
        E.set_dir_speed(u, 0.7853982, 0)        ---原作 SET_DIR_AND_SPEED −π/4 0
        E.set_accel(u, 0.03333334)              ---SET_ACCELERATION
    end)
    add(5140, function() return "die" end)
    return s
end
local SUB29 = make_sprinkler(30)
local SUB31 = make_sprinkler(32)

---连续 [−1,1) 随机符（= 原作 `rndSgn`）。见上面 Sub30 的注释。
local function rnd_sgn() return ran:Float(0, 1) * 2 - 1 end

---Sub30（Sub29 的枪）：每 exI2 = 2 帧一发，两发一组：
---  第一发 弹种 2 / 色 6：方向 = 现抽的 ±π/4 + 自机方向，速度 = 现抽的 [0,1) + lf2(=1)
---  第二发 弹种 2 / 色 4：方向 = 现抽的 ±π/2 + 自机方向，速度同上
---（原作 `FLOAT_MUL2 lf0 rndSgn a` + `FLOAT_ADD lf0 angToPl`：我们口径下就是
---  `rnd_sgn()*a + E.aim_at(...)`。★ `rndSgn` = GetRandomF32Signed() 是**连续**的
---  [−1,1)（EclOperandsFloat.cpp:56 / Global.cpp:1231-1237）——`ran:Sign()` 是离散 ±1，
---  会把整片锥形随机弹压成 ±a 两条线，所以本卡自己定义一个连续的。）
local SUB30
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        u.exi2 = 2                              ---SET_INT exI2 2（Lunatic）
        u.lf2 = 1                               ---SET_FLOAT lf2 1
    end)
    local head = #s + 1
    add(0, function(u)
        u.lf0 = rnd_sgn() * 0.7853982 + E.aim_at(u.wx, u.wy)
        u.lf1 = ran:Float(0, 1) + u.lf2
        E.shoot(u, { op = 97, type = 2, color = 6, count1 = 1, count2 = 1,
                     speed1 = u.lf1, speed2 = 0.5, angle = u.lf0, step = 0, flags = 0x203 })
    end)
    add(0, function(u, c) c.stall = u.exi2 end)
    add(0, function(u)
        u.lf0 = rnd_sgn() * 1.57079637 + E.aim_at(u.wx, u.wy)
        u.lf1 = ran:Float(0, 1) + u.lf2
        E.shoot(u, { op = 97, type = 2, color = 4, count1 = 1, count2 = 1,
                     speed1 = u.lf1, speed2 = 0.5, angle = u.lf0, step = 0, flags = 0x203 })
    end)
    add(0, function(u, c) c.stall = u.exi2 end)
    add(0, function() return { t = 0, pc = head } end)
    SUB30 = s
end

---Sub32（Sub31 的枪）：同 Sub30 的骨架，差别：exI2 = 5、lf2 = 2.5、两发都带
---`SET_BULLET_TRANSFORM 槽0 kind 0x80（CHANGE_DIRECTION_AIMED）`（60 帧后把弹角设成
---「当时朝自机的方向 + f0」——f0 都是 0，所以就是朝自机）、
---flags 多 0x80。第一发 弹种 2 / 色 6，第二发 弹种 2 / 色 4。
---回环头是**记录写入**那条（`JUMP 0` 回 @0x3030），所以每轮都重挂一次记录。
local SUB32
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        u.exi2 = 5                              ---SET_INT exI2 5（Lunatic）
        u.lf2 = 2.5                             ---SET_FLOAT lf2 2.5
    end)
    local head = #s + 1
    add(0, function(u)
        E.record(u, 0, K.AIMED, 0, 60, 1, 0, 1.4)   ---槽0：60 帧后转成自机狙、速度 1.4
        u.lf0 = rnd_sgn() * 0.7853982
        u.lf0 = u.lf0 + E.aim_at(u.wx, u.wy)
        u.lf1 = ran:Float(0, 1) + u.lf2
        E.shoot(u, { op = 97, type = 2, color = 6, count1 = 1, count2 = 1,
                     speed1 = u.lf1, speed2 = 0.5, angle = u.lf0, step = 0, flags = 0x282 })
    end)
    add(0, function(u, c) c.stall = u.exi2 end)
    add(0, function(u)
        u.lf0 = rnd_sgn() * 1.57079637
        E.record(u, 0, K.AIMED, 0, 60, 1, 0, 2)     ---槽0：60 帧后转成自机狙、速度 2
        u.lf0 = u.lf0 + E.aim_at(u.wx, u.wy)
        u.lf1 = ran:Float(0, 1) + u.lf2
        E.shoot(u, { op = 97, type = 2, color = 4, count1 = 1, count2 = 1,
                     speed1 = u.lf1, speed2 = 0.5, angle = u.lf0, step = 0, flags = 0x282 })
    end)
    add(0, function(u, c) c.stall = u.exi2 end)
    add(0, function(u) return { t = 0, pc = head } end)
    SUB32 = s
end

---Sub33（时间轴生成的清场器）：当帧清掉全场子弹 + 杀掉所有非 BOSS 敌人（含自己）。
local SUB33 = {
    { 0, function() E.wipe(); E.kill_all() end },
    { 0, function() return "die" end },
}

---Sub34/36（时间轴生成的「枪架」，life 500）：从场地上方插进来（原作 MOVE_IN_DIR 50 4 π/2 2/3
---⇒ 我们 −π/2），t=50 起原地转向下（原作 SET_DIR_AND_SPEED π/2 1）、把 lf0/lf1 设好，
---t=50/60/70/80 各撒一只 life 100 的使魔 Sub35；t=5080 退场。
---34 与 36 只差：插进来的速度 2 / 3，lf1 = +0.05235988 / −0.05235988（我们口径）。
local function make_platform(speed, angvel)
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u) E.move_in_dir(u, 50, 4, -1.57079637, speed) end)
    add(50, function(u)
        E.set_dir_speed(u, -1.57079637, 1)        ---原作 SET_DIR_AND_SPEED π/2 1
        u.lf0 = -1.57079637                       ---原作 SET_FLOAT lf0 π/2
        u.lf1 = angvel
        E.spawn_inherit(u, 35, 100, -2)
    end)
    add(60, function(u) E.spawn_inherit(u, 35, 100, -2) end)
    add(70, function(u) E.spawn_inherit(u, 35, 100, -2) end)
    add(80, function(u) E.spawn_inherit(u, 35, 100, -2) end)
    add(5080, function() return "die" end)
    return s
end
local SUB34 = make_platform(2,  0.05235988)
local SUB36 = make_platform(3, -0.05235988)

---Sub38（中 BOSS 的「塔」外壳）：t=0 标成 BOSS（`SET_BOSS 0`）、关掉 DAMAGEABLE 与
---出屏回收（`DISABLE_INTERACTION_FLAGS 20`）、前 60 帧免伤计时器（BOSS ⇒ 只吃 1/9）、
---`SET_LIFE 14000`（填在时间轴表的 life）、`SET_TIMER_CALLBACK 2040 45`（超时 34 秒 →
---二阶段）、`SET_DEATH_CALLBACK 45`（打光血 → 二阶段，不是死）；
---同时把机身挪到 (224,256)（原作 SET_POSITION 416 −32）、60 帧插值到 (0,96)
---（原作 MOVE_TO 60 4 192 128）；t=120 设活动范围 x∈[−160,160] y∈[96,176]
---（原作 SET_MOVEMENT_BOUNDS 32 48 352 128）并 `CALL 39`（同一只敌人接着跑主循环）。
local SUB38
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        E.boss(u)                               ---SET_BOSS 0
        E.disable_if(u, 20)                     ---DISABLE_INTERACTION_FLAGS 20
        E.reduction(u, 60)                      ---SET_DAMAGE_REDUCTION_TIMER 60
        ---★ 原作这里还有 `SET_TIMER_CALLBACK 2040 45`（34 秒）与 `SET_DEATH_CALLBACK 45`：
        ---  一阶段**到点或被打死都变二阶段**（Sub45）。移植版把两阶段拆成两张卡
        ---  （1007 = 本卡、1008 = Sub45），换卡由 LIST 驱动 ⇒ 这两条不实现。
        E.set_position(u, 224, 256)
        E.move_to(u, 60, 4, 0, 96)
    end)
    add(120, function(u)
        E.set_bounds(u, -160, 96, 160, 176)
        E.call(u, 39)
    end)
    add(120, function() return "die" end)   ---39 号 RETURN 了才会走到这里（兜底）
    SUB38 = s
end

---Sub39（BOSS 本体，Sub38 在 t=120 CALL 进来）：t=0 先 `CALL 40`（开局 64 轮爆发，
---约 66 帧），然后进 t=120..360 的循环：
---  t=120  `MOVE_RANDOM_IN_BOUNDS 60 4 1`、exI0 = 16、lf1 = 1、
---         lf0 = 自机方向 + π/2（我们口径）；随后**同一帧**跑 16 轮：
---         每轮撒一只 Sub42 使魔（`SPAWN_FAM_AT_OFFSET 42 0 0 300 −2`，原地朝 lf0 飞）、
---         并把 lf0 转 +0.1963495（= 11.25°）；exI3 > 0 时这 16 轮每轮再甩一圈 12 发
---         （弹种 1 / 色 6、step 0.01636246 = 0.9375°）。首轮 exI3 还是 0 ⇒ 不出弹。
---  t=180  `CALL 41`（第二轮爆发）。
---  t=300  再来一遍 16 轮（这一遍不论 exI3 **都**出弹，弹种 1 / 色 2、step 取负）。
---  t=360  `INT_INC exI3`、`JUMP 0` 回 t=120 重来。
---Sub39（中 BOSS 一阶段主循环，Sub38 在 t=120 CALL 进来）：
---  t=0    `ENABLE_INTERACTION_FLAGS 4`（塔壳打完 ⇒ 可以打了）、`SET_ITEM_DROP_COUNTS 10 5`、
---         `SET_INT exI3 0`、`CALL 40`（开局 64 轮爆发）。
---  t=120  `MOVE_RANDOM_IN_BOUNDS 60 4 1`、exI0 = 16、lf1 = 1；随后**同一帧** 16 轮：
---         ★ `FLOAT_SUB2 lf0 angToPl π/2` 在 @0x387c，**进循环前只算一次**；内循环的回环头
---         是 `NORMALIZE_ANGLE lf0` @0x38a8（JUMP_DEC 的 -296 落在 14504 = 0x38a8，
---         **不是** FLOAT_SUB2）⇒ 16 只使魔的方向逐只转开 11.25°、扫过 180°。
---         每轮再撒一只 Sub42 使魔（原地朝当轮 lf0 飞）、lf0 转 11.25°
---         （原作 `FLOAT_ADD lf0 0.1963495` ⇒ 我们**减** 11.25°：见文件头「角整体取反」），
---         exI3 > 0 时甩一圈 12 发（弹种 1 / 色 6、step 0.01636246）。首轮 exI3 = 0 ⇒ 不出弹。
---  t=180  `CALL 41`（第二轮爆发）。
---  t=300  再来一遍 16 轮（这一遍**都**出弹，弹种 1 / 色 2、step 取负）。
---  t=360  `INT_INC exI3`、`JUMP 0` 回 **t=0 的 `CALL 40`**（原作回环头 `@0x3840`）。
local SUB39
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        E.enable_if(u, 4)                       ---ENABLE_INTERACTION_FLAGS 4
        E.drop_counts(u, 10, 5)                 ---SET_ITEM_DROP_COUNTS 10 5
        u.exi3 = 0                              ---SET_INT exI3 0
    end)
    local call40 = #s + 1
    add(0, function(u) E.call(u, 40) end)       ---#3 CALL 40（外循环回到这里）
    add(120, function(u)
        E.move_random_bounds(u, 60, 4, 1)       ---#4
        u.exi0 = 16                             ---#5
        u.lf1 = 1                               ---#7
    end)
    add(120, function(u)                            ---#6 FLOAT_SUB2：进内循环前只算一次
        u.lf0 = E.aim_at(u.wx, u.wy) + 1.57079637
    end)
    local head = #s + 1                         ---#8（内循环头 = NORMALIZE_ANGLE）
    add(120, function(u)
        u.lf0 = E.norm(u.lf0)                       ---★ 回环头是 NORMALIZE_ANGLE（不重算自机方向）
    end)
    add(120, function(u)
        E.spawn_offset(u, 42, 0, 0, 300, -2)    ---#9
        E.offset(u, 0, 0)                       ---#10
        if u.exi3 > 0 then                      ---#11 JMP_IF_INT_LE exI3 0
            E.shoot(u, { op = 99, type = 1, color = 6, count1 = 1, count2 = 12,
                         speed1 = 3, speed2 = 0.8, angle = u.lf0,
                         step = -0.01636246, flags = 0x202 })    ---#15（Lunatic；原作 step = +0.0163624622 ⇒ 我们取反）
        end
        u.lf0 = u.lf0 - 0.1963495               ---#16 FLOAT_ADD lf0 0.1963495（取反）
    end)
    add(120, function(u)                        ---#17 JUMP_DEC → #6
        u.exi0 = u.exi0 - 1
        if u.exi0 > 0 then return { t = 120, pc = head } end
    end)
    add(180, function(u) E.call(u, 41) end)     ---#18
    add(300, function(u)
        E.move_random_bounds(u, 60, 4, 1)       ---#19
        u.exi0 = 16                             ---#20
        u.lf1 = 1                               ---#21
    end)
    add(300, function(u)                            ---#22 FLOAT_SUB2：进内循环前只算一次
        u.lf0 = E.aim_at(u.wx, u.wy) + 1.57079637
    end)
    local head2 = #s + 1                        ---#23（内循环头 = NORMALIZE_ANGLE）
    add(300, function(u)
        u.lf0 = E.norm(u.lf0)                       ---★ 回环头是 NORMALIZE_ANGLE（不重算自机方向）
    end)
    add(300, function(u)
        E.spawn_offset(u, 42, 0, 0, 300, -2)    ---#24
        E.offset(u, 0, 0)                       ---#25
        E.shoot(u, { op = 99, type = 1, color = 2, count1 = 1, count2 = 12,
                     speed1 = 3, speed2 = 0.8, angle = u.lf0,
                     step = 0.01636246, flags = 0x202 })         ---#29（Lunatic；原作 step = −0.0163624622 ⇒ 我们取反）
        u.lf0 = u.lf0 - 0.1963495               ---#30 FLOAT_ADD lf0 0.1963495（取反）
    end)
    add(300, function(u)                        ---#31 JUMP_DEC → #22
        u.exi0 = u.exi0 - 1
        if u.exi0 > 0 then return { t = 300, pc = head2 } end
    end)
    add(300, function(u) u.exi3 = u.exi3 + 1 end)   ---#32 INT_INC exI3
    add(360, function() return { t = 0, pc = call40 } end)  ---#33 JUMP 0 → CALL 40
    SUB39 = s
end

---Sub40（Sub39 的 CALL 目标 1）：lf2 = 现抽的随机角、exI0 = 64；每轮把发射点沿 lf2
---摆到半径 64 处（`SET_SHOOT_OFFSET cos·64, sin·64`）、lf2 转 +11.25°，然后打两发扇：
---  槽 0 = CULL(120 帧)；槽 1 = 相对折向（60 帧后弹角 ∓90°、速度 lf7）；槽 2 = 换贴图(2, 色4)。
---  主扇：弹种 2 / 色 2、li7 = 9 路、速度 3→0.8、张角 lf7 = 0.09817477（5.625°）、flags 0x6242。
---  自机在 96 px 以内时再补一发 3 路自机狙（弹种 3 / 色 6、速度 3→0.8）。
---JUMP_DEC 的 exI0 走到 0 就 RETURN。
local SUB40
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        u.lf2 = ran:Float(-PI, PI)              ---SET_FLOAT lf2 rndAngle（[−π,π)）
        u.exi0 = 64
        E.record(u, 0, K.CULL, 0, 120, -1, -1, -1)
    end)
    local head = #s + 1
    add(0, function(u)
        E.offset(u, math.cos(u.lf2) * 64, math.sin(u.lf2) * 64)
        u.li0 = u.exi0 % 2                      ---INT_MOD2 li0 exI0 2
        u.lf7 = 1.8                             ---SET_FLOAT lf7 1.8（Lunatic）
        if u.li0 == 0 then
            E.record(u, 1, K.REL, 1, 60, 1, 1.57079637, u.lf7)
        else
            E.record(u, 1, K.REL, 1, 60, 1, -1.57079637, u.lf7)
        end
        E.record(u, 2, K.SPRITE, 0, 2, 4, -1, -1)
        u.lf2 = u.lf2 - 0.1963495               ---FLOAT_ADD lf2 0.1963495（取反）
        u.lf7 = 0.09817477                      ---SET_FLOAT lf7（Lunatic）
        u.li7 = 9                               ---SET_INT li7（Lunatic）
        E.shoot(u, { op = 97, type = 2, color = 2, count1 = u.li7, count2 = 1,
                     speed1 = 3, speed2 = 0.8, angle = u.lf2, step = u.lf7, flags = 0x6242 })
        local dx, dy = player.x - u.wx, player.y - u.wy
        if dx * dx + dy * dy < 96 * 96 then
            E.shoot(u, { op = 96, type = 3, color = 6, count1 = 3, count2 = 1,
                         speed1 = 3, speed2 = 0.8, angle = u.lf2, step = u.lf7, flags = 0x202 })
        end
    end)
    add(1, function(u)
        u.exi0 = u.exi0 - 1
        if u.exi0 > 0 then return { t = 0, pc = head } end
    end)
    add(1, function() return "ret" end)
    SUB40 = s
end

---Sub41（Sub39 的 CALL 目标 2）：同 Sub40，差别：lf7 = 1.4、li7 = 7、槽 2 换色 8、
---lf2 每轮**减** 11.25°；主扇弹种 2 / 色 6，自机狙 3 发、速度 4→0.8。
local SUB41
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        u.lf2 = ran:Float(-PI, PI)
        u.exi0 = 64
        E.record(u, 0, K.CULL, 0, 120, -1, -1, -1)
    end)
    local head = #s + 1
    add(0, function(u)
        E.offset(u, math.cos(u.lf2) * 64, math.sin(u.lf2) * 64)
        u.li0 = u.exi0 % 2
        u.lf7 = 1.4
        if u.li0 == 0 then
            E.record(u, 1, K.REL, 1, 60, 1, 1.57079637, u.lf7)
        else
            E.record(u, 1, K.REL, 1, 60, 1, -1.57079637, u.lf7)
        end
        E.record(u, 2, K.SPRITE, 0, 2, 8, -1, -1)
        u.lf2 = u.lf2 + 0.1963495               ---FLOAT_SUB lf2 0.1963495（取反）
        u.lf7 = 0.09817477
        u.li7 = 7
        E.shoot(u, { op = 97, type = 2, color = 6, count1 = u.li7, count2 = 1,
                     speed1 = 3, speed2 = 0.8, angle = u.lf2, step = u.lf7, flags = 0x6242 })
        local dx, dy = player.x - u.wx, player.y - u.wy
        if dx * dx + dy * dy < 96 * 96 then
            E.shoot(u, { op = 96, type = 3, color = 6, count1 = 3, count2 = 1,
                         speed1 = 4, speed2 = 0.8, angle = u.lf2, step = u.lf7, flags = 0x202 })
        end
    end)
    add(1, function(u)
        u.exi0 = u.exi0 - 1
        if u.exi0 > 0 then return { t = 0, pc = head } end
    end)
    add(1, function() return "ret" end)
    SUB41 = s
end

---Sub42（Sub39 撒出的使魔，life 300）：出生当帧就按父机当时的 lf0/lf1 直线飞出去
---（`SET_DIR_AND_SPEED lf0 lf1`，op91 不跟随父机），t=5001 退场。
local SUB42
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u) E.set_dir_speed(u, u.lf0, u.lf1) end)
    add(1, function(u) E.contact(u) end)        ---t=1 ENABLE_INTERACTION_FLAGS 3（撞到自机会死）
    add(5001, function() return "die" end)
    SUB42 = s
end

---★ Sub43（二阶段超时回调）/ Sub44（二阶段死亡回调）**不实现**：两条都是
---  `SET_BOSS −1` + `DISABLE_MOVEMENT_BOUNDS` + 60 帧飞到 (64,256) + TERMINATE 的离场演出
---  （Sub44 另加 `SPAWN_ITEM 5`），原作靠它解除时间轴的 WAIT_FOR_BOSS_DEFEAT。
---  移植版里「二阶段打完」= 卡 1008 结束，后一张卡（1009 道中後段）由 LIST 接上
---  ⇒ 不需要 `SET_BOSS`，离场演出也交给卡结束那一套（同其它卡的口径）。

---Sub45（中 BOSS 二阶段 = 卡 1008 的脚本）：t=0 重新开打 ——
---  `ENABLE_INTERACTION_FLAGS 4`、`SET_ITEM_DROP_COUNTS 10 5`、`SET_DAMAGE_REDUCTION_TIMER 320`
---  （BOSS ⇒ 前 320 帧只吃 1/9）、`SET_LIFE 11000`、`MOVE_TO 60 4 192 128`（我们 (0,96)：
---  起点 = 一阶段结束时的位置，由卡 1007 经 SAVE_POS 传过来）。
---  t=180  `SET_CHILD_ECL 0 46` / `1 47`（两把枪）、exI0 = 16、lf0 = 自机方向 + π/2
---         （`FLOAT_SUB2` @0x4410，进内循环前只算一次；回环头是 `NORMALIZE_ANGLE` @0x443c
---         —— JUMP_DEC 的 -92 就落在这里）⇒ 16 只使魔方向逐只转开 11.25°、扫过 180°
---         （原作 `FLOAT_ADD lf0 0.1963495` ⇒ 我们**减** 11.25°，同 SUB39）。
---  t=350  再来 16 轮（同样每轮只归一化）。
---  t=520  `INT_INC exI3`、`JUMP 180` 回外循环头（`SET_INT exI0 16` 那条）。
local SUB45
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        E.enable_if(u, 4)                       ---ENABLE_INTERACTION_FLAGS 4
        E.drop_counts(u, 10, 5)                 ---SET_ITEM_DROP_COUNTS 10 5
        E.reduction(u, 320)                     ---SET_DAMAGE_REDUCTION_TIMER 320
        E.set_life(u, 11000)                    ---SET_LIFE 11000
        E.move_to(u, 60, 4, 0, 96)              ---MOVE_TO 60 4 192 128
        ---★ 原作这里还有 `SET_TIMER_CALLBACK 1560 43`（26 秒）与 `SET_DEATH_CALLBACK 44`
        ---  （到点 / 被打死都走离场脚本，见上面 Sub43/Sub44 那段注），移植版不实现。
    end)
    add(180, function(u) u.exi3 = 0 end)        ---#9 SET_INT exI3 0
    ---★ 46 / 47 用的是**子 context 自己的变量银行**（挂上时 memcpy 本体一份，见 set_child）：两把枪
    ---  也各用 exI0 当扇形序号（从 64 起 +1），**不会**碰下面循环用的本体 exI0 —— 原作就是这么隔离的。
    add(180, function(u) E.child(u, 46, 0) end) ---#10 SET_CHILD_ECL 0 46
    add(180, function(u) E.child(u, 47, 1) end) ---#11 SET_CHILD_ECL 1 47
    local loop = #s + 1                         ---#12（外循环头）
    add(180, function(u) u.exi0 = 16 end)
    add(180, function(u)                            ---#13 FLOAT_SUB2：进内循环前只算一次
        u.lf0 = E.aim_at(u.wx, u.wy) + 1.57079637
    end)
    local head = #s + 1                         ---#15（内循环头 = NORMALIZE_ANGLE）
    add(180, function(u)
        u.lf0 = E.norm(u.lf0)                       ---★ 回环头是 NORMALIZE_ANGLE（不重算自机方向）
    end)
    add(180, function(u)
        u.lf1 = 1                               ---#14
        E.spawn_offset(u, 42, 0, 0, 300, -2)    ---#16
        E.offset(u, 0, 0)                       ---#17
        u.lf0 = u.lf0 - 0.1963495               ---#18 FLOAT_ADD lf0 0.1963495（取反）
    end)
    add(180, function(u)                        ---#19 JUMP_DEC → #13
        u.exi0 = u.exi0 - 1
        if u.exi0 > 0 then return { t = 180, pc = head } end
    end)
    add(350, function(u) u.exi0 = 16 end)       ---#20
    add(350, function(u) u.lf1 = 1 end)         ---#21
    add(350, function(u)                            ---#22 FLOAT_SUB2：进内循环前只算一次
        u.lf0 = E.aim_at(u.wx, u.wy) + 1.57079637
    end)
    local head2 = #s + 1                        ---#23（内循环头 = NORMALIZE_ANGLE）
    add(350, function(u)
        u.lf0 = E.norm(u.lf0)                       ---★ 回环头是 NORMALIZE_ANGLE（不重算自机方向）
    end)
    add(350, function(u)
        E.spawn_offset(u, 42, 0, 0, 300, -2)    ---#24
        E.offset(u, 0, 0)                       ---#25
        u.lf0 = u.lf0 - 0.1963495               ---#26 FLOAT_ADD lf0 0.1963495（取反）
    end)
    add(350, function(u)                        ---#27 JUMP_DEC → #22
        u.exi0 = u.exi0 - 1
        if u.exi0 > 0 then return { t = 350, pc = head2 } end
    end)
    add(350, function(u) u.exi3 = u.exi3 + 1 end)   ---#28 INT_INC exI3
    add(520, function() return { t = 180, pc = loop } end)  ---#29 JUMP 180
    SUB45 = s
end

---Sub46 / Sub47（二阶段挂在 BOSS 身上的两把枪，`SET_CHILD_ECL`）：
---  无限循环（`JUMP 0` 回 t=0 的开头，原作带一条够不着的 RETURN）：每 4 帧一轮 ——
---  槽 0 = CULL(120 帧)；槽 1 = 相对折向（60 帧后弹角 ∓90°、速度 1.1）；槽 2 = 换贴图
---  （46 号色 4/3 交替、47 号色 8/7 交替）。
---  46：lf2 从 0 起每轮 0.1847996（10.6°）、主扇弹种 2 / 色 2、Lunatic li7 = 7 路、
---      lf7 = 0.1308997；自机 96 px 内补一发 3 路自机狙（弹种 3 / 色 6、速度 4）。
---  47：lf2 从 π/2 起每轮反向 0.1847996、主扇弹种 2 / 色 6、li7 = 9 路；其余同 46。
---  ★ lf2 同时当 `SET_SHOOT_OFFSET` 的角（cos·64, sin·64）与主扇的发射角 ⇒ 必须**存我们
---    口径**（= −lf2_原作）：原作 `SET_FLOAT lf2 0` / `π/2` ⇒ 这里 0 / −π/2；
---    `FLOAT_ADD lf2 0.1847996`（46）⇒ 这里**减**、`FLOAT_SUB`（47）⇒ 这里**加**。
local SUB46
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        u.lf2 = 0                               ---SET_FLOAT lf2 0
        u.exi0 = 64
        E.record(u, 0, K.CULL, 0, 120, -1, -1, -1)
    end)
    local head = #s + 1
    add(0, function(u)
        E.offset(u, math.cos(u.lf2) * 64, math.sin(u.lf2) * 64)
        u.li0 = u.exi0 % 2                      ---INT_MOD2 li0 exI0 2
        if u.li0 == 0 then
            ---★ 原作 li0==0 走 `SET_BULLET_TRANSFORM 1 … -1.570796 1.1`（@0x4680 落点前
            ---  的那条，`JMP_IF_INT_NE li0 0` @0x4660 跳到 +1.570796 那条）⇒ 我们取反 +π/2。
            E.record(u, 1, K.REL, 1, 60, 1, 1.57079637, 1.1)
            E.record(u, 2, K.SPRITE, 0, 2, 4, -1, -1)
        else
            E.record(u, 1, K.REL, 1, 60, 1, -1.57079637, 1.1)
            E.record(u, 2, K.SPRITE, 0, 2, 3, -1, -1)
        end
        u.lf2 = E.norm(u.lf2 - 0.184799567)       ---FLOAT_ADD lf2 0.184799567（取反）
        u.lf7 = 0.1308997                       ---SET_FLOAT lf7（Lunatic）
        u.li7 = 7                               ---SET_INT li7（Lunatic）
        E.shoot(u, { op = 97, type = 2, color = 2, count1 = u.li7, count2 = 1,
                     speed1 = 3, speed2 = 0.8, angle = u.lf2, step = u.lf7, flags = 0x6242 })
        local dx, dy = player.x - u.wx, player.y - u.wy
        if dx * dx + dy * dy < 96 * 96 then
            E.shoot(u, { op = 96, type = 3, color = 6, count1 = 3, count2 = 1,
                         speed1 = 4, speed2 = 0.8, angle = u.lf2, step = 0.09817477, flags = 0x202 })
        end
        u.exi0 = u.exi0 + 1                     ---INT_INC exI0
    end)
    add(4, function() return { t = 0, pc = head } end)   ---JUMP 0 → 回 t=0
    SUB46 = s
end

local SUB47
do
    local s = {}
    local function add(t, fn) s[#s + 1] = { t, fn } end
    add(0, function(u)
        u.lf2 = -1.57079637                       ---SET_FLOAT lf2 π/2（取反）
        u.exi0 = 64
        E.record(u, 0, K.CULL, 0, 120, -1, -1, -1)
    end)
    local head = #s + 1
    add(0, function(u)
        E.offset(u, math.cos(u.lf2) * 64, math.sin(u.lf2) * 64)
        u.li0 = u.exi0 % 2
        if u.li0 == 0 then
            ---★ 同 Sub46：原作 li0==0 走 −1.570796 那条 ⇒ 我们取反 +π/2。
            E.record(u, 1, K.REL, 1, 60, 1, 1.57079637, 1.1)
            E.record(u, 2, K.SPRITE, 0, 2, 8, -1, -1)
        else
            E.record(u, 1, K.REL, 1, 60, 1, -1.57079637, 1.1)
            E.record(u, 2, K.SPRITE, 0, 2, 7, -1, -1)
        end
        u.lf2 = E.norm(u.lf2 + 0.184799567)       ---FLOAT_SUB lf2 0.184799567（取反）
        u.lf7 = 0.1308997
        u.li7 = 9
        E.shoot(u, { op = 97, type = 2, color = 6, count1 = u.li7, count2 = 1,
                     speed1 = 3, speed2 = 0.8, angle = u.lf2, step = u.lf7, flags = 0x6242 })
        local dx, dy = player.x - u.wx, player.y - u.wy
        if dx * dx + dy * dy < 96 * 96 then
            E.shoot(u, { op = 96, type = 3, color = 6, count1 = 3, count2 = 1,
                         speed1 = 4, speed2 = 0.8, angle = u.lf2, step = 0.09817477, flags = 0x202 })
        end
        u.exi0 = u.exi0 + 1
    end)
    add(4, function() return { t = 0, pc = head } end)
    SUB47 = s
end

