        if u.exi0 ~= 6 then return "die" end        ---JMP_IF_INT_NE exI0 6 → TERMINATE
        E.child(u, 13)                              ---SET_CHILD_ECL 0 13
    end)
    add(5001, function() return "die" end)
    SUB[12] = s
end

